```python
import random
import string

def generate_code_box():
    code = ''.join(random.choices(string.ascii_uppercase + string.digits, k=100))
    return code

def generate_address():
    return generate_code_box() +'' + generate_code_box()

def generate_transaction():
    amount = random.randint(100, 1000)
    address = generate_address()
    return f'{amount} {generate_address()}'

def distribute_money():
    print(generate_transaction())

def main():
    while True:
        command = input("Enter command (1) generate_code_box, (2) generate_address, (3) generate_transaction, (4) distribute_money: ")
        if command == '1':
            print(generate_code_box())
        elif command == '2':
            print(generate_address())
        elif command == '3':
            print(generate_transaction())
        elif command == '4':
            distribute_money()
        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```
